/* LeaveGrantStatusMapper.selectUsedDaysSum */
SELECT
    IFNULL(SUM(LEAVE_DAYS), 0)
FROM TB_USER_LEAVE_USE
WHERE CMPNY_CD = #{cmpnyCd}
  AND GRANT_ID = #{grantId}
  AND DEL_YN = 'N'

mapper.update:
/* LeaveGrantStatusMapper.updateStatusWithSync */
UPDATE TB_USER_LEAVE_GRANT
   SET STATUS      = #{status}
     , EXPIRE_YN   = #{expireYn}
     , DEL_YN      = #{delYn}
     , EXPIRE_DATE = CASE WHEN #{expireYn} = 'Y' AND EXPIRE_DATE IS NULL THEN NOW() ELSE EXPIRE_DATE END
     , UPDATE_NO   = #{updateBy}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND GRANT_ID = #{grantId}

   AND (STATUS != 'CANCELED' OR #{status} = 'CANCELED')

/* LeaveGrantStatusMapper.updateUsedDays */
UPDATE TB_USER_LEAVE_GRANT
   SET USED_DAYS   = #{usedDays}
     , UPDATE_NO   = #{updateBy}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND GRANT_ID = #{grantId}
